UPDATE zw_advice
RECIPIENT_ID = #{recipientId}, SENDER_ID = #{senderId}, ADVICE_TYPE = #{adviceType}, ADVICE_STATUS = #{adviceStatus}, ADVICE_DESC = #{adviceDesc}, SENDER_TYPE = #{senderType},
WHERE ADVICE_ID = #{adviceId}

mapper.select:
SELECT a.*, sr.NAME as SENDER_NAME, rr.NAME as RECIPIENT_NAME, at.CODE_DESC as ADVICE_TYPE_NAME, ast.CODE_DESC as ADVICE_STATUS_NAME, st.CODE_DESC as SENDER_TYPE_NAME, GROUP_CONCAT(i.IMAGE_URL ORDER BY i.CREATE_TIME) as IMAGE_URLS FROM zw_advice a LEFT JOIN g_user sr ON a.SENDER_ID = sr.USER_ID LEFT JOIN g_user rr ON a.RECIPIENT_ID = rr.USER_ID LEFT JOIN g_code at ON a.ADVICE_TYPE = at.CODE_ID LEFT JOIN g_code ast ON a.ADVICE_STATUS = ast.CODE_ID LEFT JOIN g_code st ON a.SENDER_TYPE = st.CODE_ID LEFT JOIN zw_advice_image i ON a.ADVICE_ID = i.ADVICE_ID
AND a.RECIPIENT_ID = #{recipientId}
AND a.SENDER_ID = #{senderId}
AND a.ADVICE_TYPE = #{adviceType}
AND a.ADVICE_STATUS = #{adviceStatus}
GROUP BY a.ADVICE_ID, sr.NAME, rr.NAME, at.CODE_DESC, ast.CODE_DESC, st.CODE_DESC ORDER BY a.CREATE_TIME DESC
